+const splitTracks = (template: string | undefined): string[] => {
+	if (!template) return [];
+	const tracks: string[] = [];
+	let depth = 0;
+	let token = '';
+	for (const character of template.trim()) {
+		if (character === '(') depth++;
+		if (character === ')') depth--;
+		if (/\\s/.test(character) && depth === 0) {
+			if (token) tracks.push(token);
+			token = '';
+		} else {
+			token += character;
+		}
+	}
+	if (token) tracks.push(token);
+	return tracks;
+};
+
+const parseTrack = (value: string): Track => {
+	if (value === 'auto') return {type: 'auto'};
+	const minmax = /^minmax\\(\\s*(\\d+(?:\\.\\d+)?)\\s*,\\s*(\\d+(?:\\.\\d+)?(?:fr)?)\\s*\\)$/.exec(value);
+	if (minmax) {
