+		if (minmax[2].endsWith('fr')) {
+			return {type: 'fr', factor: Number.parseFloat(minmax[2]), min: minimum};
+		}
+		return {type: 'fixed', size: Number(minmax[2])};
+	}
+	if (value.endsWith('fr')) {
+		return {type: 'fr', factor: Number.parseFloat(value) || 1, min: 0};
+	}
+	const size = Number(value);
+	return Number.isFinite(size) ? {type: 'fixed', size} : {type: 'auto'};
+};
+
+const parseLine = (value: number | string | undefined): [number | undefined, number | undefined] => {
+	if (typeof value === 'number') return [value, undefined];
+	if (!value) return [undefined, undefined];
+	const match = /^\\s*(\\d+)\\s*(?:\\/\\s*(\\d+)\\s*)?$/.exec(value);
+	return match ? [Number(match[1]), match[2] ? Number(match[2]) : undefined] : [undefined, undefined];
+};
+
+const resolveTracks = (tracks: Track[], available: number, gap: number, autoSizes: number[]): number[] => {
+	const sizes = tracks.map((track, index) => track.type === 'fixed' ? track.size : track.type === 'auto' ? (autoSizes[index] ?? 0) : track.min);
+	const remaining = Math.max(0, available - gap * Math.max(0, tracks.length - 1) - sizes.reduce((sum, size) => sum + size, 0));
